pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    Token token;

    function setUp() public {
        c = new airPort();
        token = new Token();
    }

    function testFuzz_property(address from, address to, uint256 v) public {
        vm.assume(from != address(0));
        vm.assume(to != address(0));
        address[] memory tos = new address[](1);
        tos[0] = to;
        bool ok = c.transfer(from, address(token), tos, v);
        assertTrue(ok, "successful transfer must return true");
    }
}

contract Token {
    uint256 public calls;
    function transferFrom(address, address, uint256) external returns (bool) {
        calls++;
        return true;
    }
}
